function qtyOf(item){ return DEFAULT_QTY[item] || ''; }

// Ingredients may be a plain string ("עגבניות") or {name, qty} for recipe-specific amounts.
function ingName(i){
  if(i == null) return '';
  if(typeof i === 'string') return i;
  return i.name || i.item || '';
}
function ingQty(i){
  if(i && typeof i === 'object' && i.qty) return i.qty;
  return qtyOf(ingName(i));
}
function recipeIngNames(r){ return (r.ingredients || []).map(ingName); }
// Parse a free-text ingredient line into {name, qty?} — supports "עגבניות — 3 יחידות", "3 יחידות עגבניות", or plain names.
function parseIngredientLine(line){
  line = norm(line || '');
  if(!line) return null;
  // "name — qty" / "name - qty" / "name: qty"
  let m = line.match(/^(.+?)\s*[—\-–:]\s*(.+)$/);
  if(m && m[1].length > 1){
    const left = norm(m[1]), right = norm(m[2]);
    // if left looks like a quantity, swap
    if(/^\d/.test(left) && !/^\d/.test(right)) return { name: right, qty: left };
    return { name: left, qty: right };
  }
  // leading quantity: "3 יחידות עגבניות" / "כף שמן זית"
  m = line.match(/^(\d+[\d\.\/]*\s*(?:יחידות?|כוסות?|כפות?|כפיות?|גרם|ק[״"]?ג|מ[״"]?ל|שיניים?|חופן)?)\s+(.+)$/i);
  if(m && m[2].length > 1) return { name: norm(m[2]), qty: norm(m[1]) };
  return { name: line };
}


// ---- Categories follow supermarket departments (since v26). Settings saved with the old category
// names (on this device or synced from someone else) are translated on read; nothing is lost.
const OLD_CATEGORY_MAP = {"ירקות": "ירקות ופירות", "פירות": "ירקות ופירות", "מוצרי חלב": "מוצרי חלב וביצים", "מזווה": "מזווה ויבש", "תיבול ואפייה": "מזווה ויבש", "קפואים": "קפואים", "טואלטיקה": "חומרי ניקוי ופארם", "חטיפים ופיצוחים": "חטיפים ומתוקים", "אחר": "אחר", "חלבונים": "בשר, עוף ודגים", "פחמימות": "מזווה ויבש"};
function migrateCategoryName(cat, item){
  if(!cat || !OLD_CATEGORY_MAP[cat] || CATALOG[cat]) return cat;
  if(item && ING_TO_CAT[item] && (cat === 'חלבונים' || cat === 'פחמימות')) return ING_TO_CAT[item];
  return OLD_CATEGORY_MAP[cat];
}
function migrateCategoryOverrides(map){
  const out = {};
  Object.keys(map || {}).forEach(item=>{
    const c = migrateCategoryName(map[item], item);
    if(c && c !== ING_TO_CAT[item]) out[item] = c;          // same as the built-in place now → no override needed
  });
  return out;
}
function migrateCategoryKeyed(map){
  const out = {};
  Object.keys(map || {}).forEach(c=>{ if(migrateCategoryName(c) === c) out[c] = map[c]; });   // icons of the old built-in categories give way to the new departments' icons
  return out;
}
// One-time clean-up when moving to departments: a saved choice that merely repeats where an item used to sit
// by default (e.g. "פתי בר" → pantry) or its old default icon would hide the new department / icon — drop it.
const CATEGORY_SETTINGS_VERSION = 2;
