// Items typed in a slightly different form still find their department and icon:
// "בננות" → "בננה", "קוטג׳" → "קוטג'", "גבינה" → "גבינה צהובה".
const _knownCache = new Map();
function knownCatalogName(item, table, strict){
  if(!item || table[item]) return item;
  const key = item + '\u0001' + (table === ING_EMOJI ? 'e' : 'c') + (strict ? 's' : '');
  if(_knownCache.has(key)) return _knownCache.get(key);
  let found = null;
  const fixed = String(item).replace(/[׳`’]/g, "'").replace(/\s+/g, ' ').trim();
  if(table[fixed]) found = fixed;
  if(!found && !/\s/.test(fixed) && fixed.length > 2){
    for(const stem of [fixed.replace(/(ות|ים|ה|ת)$/, ''), fixed.replace(/יה$/, '')]){
      for(const end of ['', 'ה', 'ות', 'ים', 'ת', 'יות']){ if(table[stem + end]){ found = stem + end; break; } }
      if(found) break;
    }
  }
  if(!found && !strict){ const pre = fixed + ' '; found = Object.keys(table).find(k=>k.startsWith(pre)) || null; }
  if(!found && /\s/.test(fixed)){ const first = fixed.split(' ')[0]; if(first.length > 2) found = knownCatalogName(first, table, true); }   // "דאודורנט עלמא" → "דאודורנט"
  if(_knownCache.size > 2000) _knownCache.clear();
  _knownCache.set(key, found);
  return found;
}
