if(+(localStorage.getItem('category_settings_v') || 1) < CATEGORY_SETTINGS_VERSION){
  dropLegacyDefaults(categoryOverrides, iconOverrides);
  try{
    localStorage.setItem('category_overrides', JSON.stringify(categoryOverrides));
    localStorage.setItem('icon_overrides', JSON.stringify(iconOverrides));
    localStorage.setItem('category_settings_v', String(CATEGORY_SETTINGS_VERSION));
  }catch(e){}
}
// An item's own icon can be an emoji or a small picture (stored as a data: URL).
function isImageIcon(v){ return typeof v === 'string' && v.startsWith('data:image/'); }
function ownEmojiOf(item){ return ING_EMOJI[item] || ING_EMOJI[knownCatalogName(item, ING_EMOJI)] || null; }
// an item without an icon of its own shows its category's icon
function builtinIconOf(item){ return ownEmojiOf(item) || categoryIconOf(catOf(item)); }
// emoji only — for places that show plain text (a picture falls back to the usual emoji there)
function iconOf(item){ const o = iconOverrides[item]; return (o && !isImageIcon(o)) ? o : builtinIconOf(item); }
function iconImageOf(item){ const o = iconOverrides[item]; if(isImageIcon(o)) return o; if(o) return null; return BUILTIN_ICON_IMAGES[item] || null; }
// for HTML: the picture when there is one, otherwise the emoji
function iconHtml(item){
  const img = iconImageOf(item);
  if(!img && !iconOverrides[item] && !ownEmojiOf(item)) return categoryIconHtml(catOf(item));
  return img ? `<img class="icon-img" src="${img.replace(/"/g, '')}" alt="">` : String(iconOf(item)).replace(/[&<>"]/g, c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
}
function setIconOverride(item, icon){
  if(icon) iconOverrides[item] = icon; else delete iconOverrides[item];
  localStorage.setItem('icon_overrides', JSON.stringify(iconOverrides));
  scheduleCategorySettingsPush();
}

let autoResetEnabled = localStorage.getItem('auto_reset_enabled') === '1';
let protectedCategories = migrateCategoryList(JSON.parse(localStorage.getItem('protected_categories')||'["מזווה ויבש"]'));
function checkDailyFridgeReset(){
  if(!autoResetEnabled) return;
  const today = new Date().toDateString();
  const last = localStorage.getItem('last_fridge_reset');
  if(last === today) return;
  [...fridge].forEach(item=>{ if(!protectedCategories.includes(catOf(item))) fridge.delete(item); });
  saveFridge();
  localStorage.setItem('last_fridge_reset', today);
}

